import { useState } from "react";
import {  useNavigate } from "react-router-dom";

const Company = () => {
  const [CompanyName, setCompanyName] = useState('');
  const [Phonenumber, setPhonenumber] = useState('');
    const [EmailAddress, setEmailAddress] = useState('');
     const [Companylocation, setCompanylocation] = useState('');
     const [Companytype, setCompanytype] = useState('');
  const [Numberofemployees, setNumberofemployees] = useState('');
  const [Companydiscription, setCompanydiscription] = useState('');

  const navigate =useNavigate();
 const handleSubmit = (e) => {
    e.preventDefault();
    const blog = {CompanyName, Phonenumber,EmailAddress, Companylocation,Companytype,Numberofemployees,Companydiscription };

    fetch('http://localhost:8000/blogs/', {
      method: 'POST',
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(blog)
    }).then(() => {
      // history.go(-1);
      navigate('');
    })
  }
 return (
    <div className="company">
      <h2>Create Your Company Account </h2>
      <form onSubmit={handleSubmit}>
        <label>Company Name</label>
        <input 
          type="text" 
          placeholder="Enter your company name"
          required 
          value={CompanyName}
          onChange={(e) => setCompanyName(e.target.value)}
        />
         <label>Phone Number:</label>
        <input 
          type="text" 
          placeholder="Enter your phone number"
          required 
          value={Phonenumber}
          onChange={(e) => setPhonenumber(e.target.value)}
        />
         <label>Email Address:</label>
        <input 
          type="text" 
          placeholder="Enter your company email address"
          required 
          value={EmailAddress}
          onChange={(e) => setEmailAddress(e.target.value)}
        />
         <label>Company Location:</label>
        <input 
          type="text" 
          placeholder="Enter Your Company location"
          required 
          value={Companylocation}
          onChange={(e) => setCompanylocation(e.target.value)}
        />
         <label>Company Type:</label>
        <input 
          type="text" 
          placeholder="e.g. Technology,Healthcare,Construction.."
          required 
          value={Companytype}
          onChange={(e) => setCompanytype(e.target.value)}
        />
        <label>Number Of Employees:</label>
        <input 
          type="text"
          placeholder="e.g. 10-50 employees" 
          required 
          value={Numberofemployees}
          onChange={(e) => setNumberofemployees(e.target.value)}
        />
     <label>Company Discription</label>
     <textarea
       required
       placeholder="Tell us about your company"
          value={Companydiscription}
          onChange={(e) => setCompanydiscription(e.target.value)}>
 </textarea>
 <br></br>
        <button>Submit</button>
      </form>
    </div>
  );
}

export default Company ;
